var btn = root_element.getElementById("qrCodeScanBtn")
console.log(btn)
let d = new frappe.ui.Dialog({
			title: __("Scan Challans or Orders"),
			fields: [
		{
			label: 'Order/Receipt ID',
			fieldname: 'qr_code',
			fieldtype: 'Data',
		},
		{
			label: 'Open Scanner',
			fieldname: 'scanbtn',
			fieldtype: 'Button',
			click: async () => {
				const images = await nativeInterface.execute('openWebViewScanner')
				d.set_value('qr_code', images?.data)

			}
		},
		{
			label: 'Submit',
			fieldname: 'submitbtn',
			fieldtype: 'Button',
			click: async () => {
				frappe.call({
					method: "edu_quality.api.scan_receipts.find_url_to_redirect_to",
					args: {
						key: d['fields_dict']['qr_code']['input'].value,
						type: "POST",
					}, callback: (r) => {
						if (r.message) {
							frappe.set_route(`/app${r.message}`)
						}
					}
				})

			}
		},


	],
		});

